/* T1-2 O2b: the flat table, exported for the inline probe in the FastCode
 * copies (RECOMP_ICALL_RESOLVE_FLAT in recomp_types.h). The table itself is
 * not changed: VAs that have a manual override get a bit in g_icall_flat_ovr
 * and the probe sends them down the old chain (manual first), so every caller
 * of recomp_lookup still gets the generated function. Called once from main.c
 * when FastCode is on, after recomp_dispatch_init. Returns the number of
 * masked VAs, -1 if there is no flat table, -2 if the self-check failed (the
 * probe then stays off: span 0). */
recomp_func_t *g_icall_flat_tab = NULL;
const uint8_t *g_icall_flat_ovr = NULL;
uint32_t g_icall_flat_base = 0x00012000u;
uint32_t g_icall_flat_span = 0;
recomp_func_t recomp_lookup_manual(uint32_t xbox_va); /* RECOMP_DISPATCH_H hides them */
recomp_func_t recomp_lookup(uint32_t xbox_va);

int recomp_dispatch_fast_init(void)
{
    uint8_t *ovr;
    int masked = 0, bad = 0;
    if (!g_flat_table || g_icall_flat_base != g_flat_base) return -1;
    ovr = (uint8_t *)calloc(((size_t)g_flat_span >> 3) + 1, 1);
    if (!ovr) return -1;
        uint32_t off = g_recomp_table[i].xbox_va - g_flat_base;
        if (off < g_flat_span && recomp_lookup_manual(g_recomp_table[i].xbox_va)) {
            ovr[off >> 3] |= (uint8_t)(1u << (off & 7u));
            masked++;
        }
    }
        uint32_t va = g_recomp_table[i].xbox_va, off = va - g_flat_base;
        recomp_func_t a = NULL, b = recomp_lookup_manual(va);
        if (!b) b = recomp_lookup(va);
        if (off < g_flat_span && !(ovr[off >> 3] & (1u << (off & 7u))))
            a = g_flat_table[off];
        if (!a) a = b;
        if (a != b) bad++;
    }
    if (bad) { free(ovr); return -2; }
    g_icall_flat_tab = g_flat_table;
    g_icall_flat_ovr = ovr;
    g_icall_flat_span = g_flat_span;
    return masked;
}


/* T1-8: lane self-test of the XMM construction helpers (recomp_types.h,
 * RECOMP_XMM_INTRIN). Compares every helper with the lane-wise reference
 * (the RECOMP_XMM_INTRIN 0 code) bit for bit, on values that include -0.0,
 * denormals, infinities and quiet/signalling NaN bit patterns, and XMM_MEM
 * against four MEM32 reads of the mapped XBE header (read only). Returns
 * the number of mismatching lanes (0 = pass). Called once from main.c. */
#include <string.h>
static int recomp_xmm_cmp(RecompXmm a, RecompXmm b)
{
    int k, bad = 0;
    for (k = 0; k < 4; k++) bad += a.u[k] != b.u[k];
    return bad;
}

int recomp_xmm_selftest(void)
{
    static const uint32_t bits[] = {
        0x00000000u, 0x80000000u, 0x3F800000u, 0xBF800000u, 0x00000001u, 0x807FFFFFu,
        0x7F800000u, 0xFF800000u, 0x7FC00000u, 0x7F800001u, 0xFFFFFFFFu, 0x12345678u };
    static const uint64_t dbits[] = {
        0x0000000000000000ull, 0x8000000000000000ull, 0x3FF0000000000000ull,
        0x0000000000000001ull, 0x7FF0000000000001ull, 0x7FF8000000000000ull,
        0xFFFFFFFFFFFFFFFFull, 0x0123456789ABCDEFull };
    int bad = 0;
    RecompXmm ref, z = XMM_ZERO();
    for (i = 0; i < 4; i++) bad += z.u[i] != 0;
    for (i = 0; i < sizeof bits / sizeof bits[0]; i++) {
        float f;
        memcpy(&f, &bits[i], 4);
        ref.q[0] = 0; ref.q[1] = 0; ref.u[0] = bits[i];
        bad += recomp_xmm_cmp(XMM_SCALAR(f), ref);
        bad += recomp_xmm_cmp(XMM_SCALAR_BITS(bits[i]), ref);
    }
    for (i = 0; i < sizeof dbits / sizeof dbits[0]; i++) {
        double d;
        memcpy(&d, &dbits[i], 8);
        ref.q[0] = dbits[i]; ref.q[1] = 0;
        bad += recomp_xmm_cmp(XMM_SCALAR_DOUBLE(d), ref);
    }
    for (i = 0; i < 64; i += 4) {
        uint32_t a = 0x00010000u + (uint32_t)i * 3u; /* XBE header, unaligned too */
        ref.u[0] = MEM32(a); ref.u[1] = MEM32(a + 4); ref.u[2] = MEM32(a + 8); ref.u[3] = MEM32(a + 12);
        bad += recomp_xmm_cmp(XMM_MEM(a), ref);
    }
    return bad;
}
